package main
import("crypto/tls";"crypto/x509";"crypto/sha256";"encoding/json";"fmt";"io";"net/http";"os";"time")
func main(){pem,_:=os.ReadFile(os.Args[1]);roots:=x509.NewCertPool();roots.AppendCertsFromPEM(pem);tr:=&http.Transport{TLSClientConfig:&tls.Config{RootCAs:roots,ServerName:"fc-lab.test",MinVersion:tls.VersionTLS13},DisableKeepAlives:true};c:=&http.Client{Transport:tr,Timeout:45*time.Second};enc:=json.NewEncoder(os.Stdout);for i:=1;i<=3;i++{start:=time.Now();r,e:=c.Get("https://154.37.155.240:19454/bytes/4194304");var n int64;h:=sha256.New();if e==nil{n,e=io.Copy(h,r.Body);r.Body.Close()};d:=time.Since(start).Seconds();err:="";if e!=nil{err=e.Error()};enc.Encode(map[string]any{"round":i,"bytes":n,"seconds":d,"mbps":float64(n)*8/d/1e6,"sha256":fmt.Sprintf("%x",h.Sum(nil)),"error":err});time.Sleep(time.Second)}}
